// Schematic map images, one per map in the pool. Generated by scripts/map-schematics.ts.
import abyss from './assets/maps/abyss.svg'
import bind from './assets/maps/bind.svg'
import breeze from './assets/maps/breeze.svg'
import haven from './assets/maps/haven.svg'
import icebox from './assets/maps/icebox.svg'
import lotus from './assets/maps/lotus.svg'
import sunset from './assets/maps/sunset.svg'

const images: Record<string, string> = {
  Abyss: abyss,
  Bind: bind,
  Breeze: breeze,
  Haven: haven,
  Icebox: icebox,
  Lotus: lotus,
  Sunset: sunset,
}

export function mapImage(map: string): string | undefined {
  return images[map]
}
